mapper.update:
update TRD_PRODUCT_DEAL
set IS_CANCEL = #{isCancel,jdbcType=VARCHAR},
    UPDATE_USER = #{updateUser,jdbcType=VARCHAR},
    UPDATE_TIME = #{updateTime,jdbcType=TIMESTAMP}
where TOTLE_TRADE_ID = #{tradeId,jdbcType=VARCHAR}

mapper.select:
select
DEAL.TRADE_ID
from TRD_PRODUCT_DEAL DEAL
left join TRD_PRODUCT_DEAL_ADD TADD
ON DEAL.TRADE_ID=TADD.TRADE_ID
where  1=1

    and    DEAL.TRADE_STATUS = #{tradeStatus,jdbcType=VARCHAR}


    and    DEAL.IS_CANCEL = #{isCancel,jdbcType=VARCHAR}




    and    DEAL.TRADE_ID = #{tradeId,jdbcType=VARCHAR}


    and    DEAL.TRADE_DATE > #{tradeDate,jdbcType=DATE}


    and    DEAL.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}


    and    TADD.portfolio_id = #{portfolioId,jdbcType=VARCHAR}

SELECT V.SEC_ACCT_ID
FROM PTL_SEC_ACCT PSA, STL_SEC_ACCT_INFO V
LEFT JOIN FIN_PRODUCT R
ON R.REGIST_ORG = V.REGIST_ORG
WHERE PSA.ACCT_NO = V.SEC_ACCT_ID
AND V.SEC_ACCT_TYPE = 'SEC'
AND V.TRADE_PLACE = #{tradeMarket}
AND PSA.PORTFOLIO_ID = #{portfolioId}
AND R.FINPROD_ID = #{finprodId}
